const list = [5, 3, 8];
list.push(1);                                   // growing array: add at the end is O(1) on average
console.log("list: " + list.join(" "));

const count = new Map();                        // key -> value, O(1) on average
for (const w of "a b a c a".split(" ")) count.set(w, (count.get(w) || 0) + 1);
console.log("count of a: " + count.get("a"));

const seen = new Set();                         // "have I seen it?", O(1) on average
let firstDup = -1;
for (const x of [4, 7, 9, 7, 4]) {
  if (seen.has(x)) { firstDup = x; break; }
  seen.add(x);
}
console.log("first duplicate: " + firstDup);

const stack = [1, 2, 3];                        // newest first: push and pop at the end
console.log("stack pop: " + stack.pop());

const queue = [1, 2, 3];                        // oldest first (shift is O(n); fine for small queues)
console.log("queue dequeue: " + queue.shift());

const sorted = [...list].sort((a, b) => a - b); // JS has no sorted set: sort a copy, O(n log n)
console.log("smallest: " + sorted[0]);
// Time: O(n) for the scans, O(n log n) for the sort. Space: O(n).

