using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        // Each collection is chosen by the operation you do most often.
        var list = new List<int> { 5, 3, 8 };
        list.Add(1);                                  // growing array: Add is O(1) on average
        Console.WriteLine("list: " + string.Join(" ", list));

        var count = new Dictionary<string, int>();    // key -> value, O(1) on average
        foreach (var w in "a b a c a".Split(' ')) {
            int c;
            count.TryGetValue(w, out c);              // c stays 0 when the key is missing
            count[w] = c + 1;
        }
        Console.WriteLine("count of a: " + count["a"]);

        var seen = new HashSet<int>();                // "have I seen it?", O(1) on average
        int firstDup = -1;
        foreach (int x in new[] { 4, 7, 9, 7, 4 }) {
            if (!seen.Add(x)) { firstDup = x; break; }  // Add returns false for a repeat
        }
        Console.WriteLine("first duplicate: " + firstDup);

        var stack = new Stack<int>(new[] { 1, 2, 3 }); // newest first
        Console.WriteLine("stack pop: " + stack.Pop());

        var queue = new Queue<int>(new[] { 1, 2, 3 }); // oldest first
        Console.WriteLine("queue dequeue: " + queue.Dequeue());

        var sorted = new SortedSet<int>(list);        // keeps keys in order, O(log n) per operation
        Console.WriteLine("smallest: " + sorted.Min);
        // Time: O(n) for the scans, O(n log n) to fill the sorted set. Space: O(n).
    }
}

