public class Main {
    static class Node { int val; Node next; Node(int v) { val = v; } }

    static Node build(int[] a) {
        Node dummy = new Node(0), tail = dummy;
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    static String show(Node h) {
        StringBuilder sb = new StringBuilder();
        for (; h != null; h = h.next) sb.append(h.val).append(h.next != null ? " " : "");
        return sb.toString();
    }

    // Time: O(n), one pass. Space: O(1), only 3 pointers.
    static Node reverse(Node head) {
        Node prev = null;                 // the part that is already reversed
        while (head != null) {
            Node next = head.next;        // save the rest of the chain first
            head.next = prev;             // turn the arrow around
            prev = head;                  // move both pointers one node forward
            head = next;
        }
        return prev;                      // prev is the new first node
    }

    public static void main(String[] args) {
        Node head = build(new int[] { 1, 2, 3, 4, 5 });
        System.out.println("input:    " + show(head));
        System.out.println("reversed: " + show(reverse(head)));
    }
}

