public class Main {
    static class Node { int val; Node next; Node(int v) { val = v; } }

    static Node build(int[] a) {
        Node dummy = new Node(0), tail = dummy;
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    // Time: O(n), one pass. Space: O(1).
    static Node middle(Node head) {
        Node slow = head, fast = head;
        // fast moves 2 steps for every 1 step of slow
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;   // fast ran out, so slow has done half the distance
    }

    public static void main(String[] args) {
        // odd length: the one middle; even length: the second of the two middles
        System.out.println("1 2 3 4 5   -> middle " + middle(build(new int[] { 1, 2, 3, 4, 5 })).val);
        System.out.println("1 2 3 4 5 6 -> middle " + middle(build(new int[] { 1, 2, 3, 4, 5, 6 })).val);
    }
}

