import java.util.ArrayDeque;

public class Main {
    // A stack on top of an array that doubles when it is full.
    static class MyStack {
        private int[] items = new int[2];
        private int count = 0;

        void push(int x) {                       // O(1) on average
            if (count == items.length) items = java.util.Arrays.copyOf(items, count * 2);
            items[count++] = x;
        }
        int pop() {                              // O(1): the newest item is at the end
            if (count == 0) throw new IllegalStateException("stack is empty");
            return items[--count];
        }
        int peek() { return items[count - 1]; }
        int size() { return count; }
    }

    public static void main(String[] args) {
        MyStack stack = new MyStack();
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int x : new int[] { 1, 2, 3 }) { stack.push(x); queue.addLast(x); }
        System.out.println("added: 1 2 3");
        System.out.println("stack pop:     " + stack.pop() + " (newest first)");
        System.out.println("stack peek:    " + stack.peek() + ", size " + stack.size());
        System.out.println("queue dequeue: " + queue.pollFirst() + " (oldest first)");
        // Space: O(n) for both.
    }
}

