  constructor() { this.items = new Array(2); this.count = 0; }

  push(x) {                                  // O(1) on average
    if (this.count === this.items.length) {
      const bigger = new Array(this.count * 2);
      for (let i = 0; i < this.count; i++) bigger[i] = this.items[i];
      this.items = bigger;
    }
    this.items[this.count++] = x;
  }
  pop() {                                    // O(1): the newest item is at the end
    if (this.count === 0) throw new Error("stack is empty");
    return this.items[--this.count];
