// A stack on top of an array that doubles when it is full.
class MyStack {
    private int[] items = new int[2];
    private int count = 0;

    public void Push(int x) {                    // O(1) on average
        if (count == items.Length) Array.Resize(ref items, count * 2);
        items[count++] = x;
    }
    public int Pop() {                           // O(1): the newest item is at the end
        if (count == 0) throw new InvalidOperationException("stack is empty");
        return items[--count];
    }
    public int Peek() { return items[count - 1]; }
    public int Count { get { return count; } }
}

class Program {
    static void Main() {
        var stack = new MyStack();
        var queue = new Queue<int>();
        foreach (int x in new[] { 1, 2, 3 }) { stack.Push(x); queue.Enqueue(x); }
        Console.WriteLine("added: 1 2 3");
        Console.WriteLine("stack pop:     " + stack.Pop() + " (newest first)");
        Console.WriteLine("stack peek:    " + stack.Peek() + ", size " + stack.Count);
        Console.WriteLine("queue dequeue: " + queue.Dequeue() + " (oldest first)");
        // Space: O(n) for both.
    }
}

