import java.util.ArrayDeque;

public class Main {
    // Time: O(n). Space: O(n) for the stack in the worst case.
    static boolean isBalanced(String s) {
        ArrayDeque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);                       // remember every opening bracket
            } else {
                if (stack.isEmpty()) return false;   // a closer with nothing open
                char open = stack.pop();             // the most recent opener must match
                if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{'))
                    return false;
            }
        }
        return stack.isEmpty();                      // nothing may be left open
    }

    public static void main(String[] args) {
        for (String s : new String[] { "([]{})", "([)]", "((", "" })
            System.out.println("\"" + s + "\" -> " + (isBalanced(s) ? "balanced" : "not balanced"));
    }
}

