import java.util.ArrayList;
import java.util.List;

public class Main {
    static class Node { int val; Node left, right; Node(int v) { val = v; } }

    static Node insert(Node n, int v) {            // builds a small search tree for the demo
        if (n == null) return new Node(v);
        if (v < n.val) n.left = insert(n.left, v); else n.right = insert(n.right, v);
        return n;
    }

    // order: 0 = pre (node first), 1 = in (node in the middle), 2 = post (node last)
    static void walk(Node n, int order, List<String> out) {
        if (n == null) return;
        if (order == 0) out.add("" + n.val);
        walk(n.left, order, out);
        if (order == 1) out.add("" + n.val);
        walk(n.right, order, out);
        if (order == 2) out.add("" + n.val);
    }

    // Height counted in nodes: an empty tree is 0, a single node is 1.
    static int height(Node n) {
        return n == null ? 0 : 1 + Math.max(height(n.left), height(n.right));
    }

    public static void main(String[] args) {
        Node root = null;
        for (int v : new int[] { 4, 2, 6, 1, 3, 5, 7 }) root = insert(root, v);
        String[] names = { "pre-order: ", "in-order:  ", "post-order:" };
        for (int order = 0; order < 3; order++) {
            List<String> out = new ArrayList<>();
            walk(root, order, out);
            System.out.println(names[order] + " " + String.join(" ", out));
        }
        System.out.println("height: " + height(root));
        // Time: O(n) for each walk. Space: O(h) call stack, h = height.
    }
}

