class Node:
    def __init__(self, val):
        self.val, self.left, self.right = val, None, None

def insert(n, v):                       # builds a small search tree for the demo
    if n is None:
        return Node(v)
    if v < n.val:
        n.left = insert(n.left, v)
    else:
        n.right = insert(n.right, v)
    return n

# order: 0 = pre (node first), 1 = in (node in the middle), 2 = post (node last)
def walk(n, order, out):
    if n is None:
        return
    if order == 0: out.append(str(n.val))
    walk(n.left, order, out)
    if order == 1: out.append(str(n.val))
    walk(n.right, order, out)
    if order == 2: out.append(str(n.val))

# Height counted in nodes: an empty tree is 0, a single node is 1.
def height(n):
    return 0 if n is None else 1 + max(height(n.left), height(n.right))

root = None
for v in [4, 2, 6, 1, 3, 5, 7]:
    root = insert(root, v)
names = ["pre-order: ", "in-order:  ", "post-order:"]
for order in range(3):
    out = []
    walk(root, order, out)
