    static class Node { int val; Node next; Node(int v) { val = v; } }

    // Time: O(n). Space: O(1).
    static boolean hasCycle(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;             // 1 step
            fast = fast.next.next;        // 2 steps
            if (slow == fast) return true;   // they can only meet inside a loop
        }
        return false;                     // fast fell off the end: no loop
    }

    public static void main(String[] args) {
        Node[] n = new Node[5];
        for (int i = 0; i < 5; i++) n[i] = new Node(i + 1);
        for (int i = 0; i < 4; i++) n[i].next = n[i + 1];
        System.out.println("1 -> 2 -> 3 -> 4 -> 5 -> end:       cycle " + (hasCycle(n[0]) ? "yes" : "no"));
        n[4].next = n[2];                 // make the last node point back to node 3
        System.out.println("1 -> 2 -> 3 -> 4 -> 5 -> back to 3: cycle " + (hasCycle(n[0]) ? "yes" : "no"));
    }
}

