public class Main {
    static class Node { int val; Node next; Node(int v) { val = v; } }

    static Node build(int[] a) {
        Node dummy = new Node(0), tail = dummy;
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    static String show(Node h) {
        StringBuilder sb = new StringBuilder();
        for (; h != null; h = h.next) sb.append(h.val).append(h.next != null ? " " : "");
        return sb.toString();
    }

    // Time: O(n + m). Space: O(1), the old nodes are re-linked, not copied.
    static Node merge(Node a, Node b) {
        Node dummy = new Node(0), tail = dummy;   // dummy: no special case for the first node
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }   // take the smaller front node
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;          // attach whatever is left over
        return dummy.next;
    }

    public static void main(String[] args) {
        Node a = build(new int[] { 1, 3, 5 }), b = build(new int[] { 2, 4, 6, 8 });
        System.out.println("a: " + show(a));
        System.out.println("b: " + show(b));
        System.out.println("merged: " + show(merge(a, b)));
    }
}

