import java.util.ArrayDeque;

public class Main {
    static class MyQueue {
        private final ArrayDeque<Integer> in = new ArrayDeque<>(), out = new ArrayDeque<>();

        void enqueue(int x) { in.push(x); }            // O(1)

        int dequeue() {                                // O(1) on average
            if (out.isEmpty()) {
                // pour only when out is empty: pouring reverses the order, so the oldest ends on top
                while (!in.isEmpty()) out.push(in.pop());
            }
            if (out.isEmpty()) throw new IllegalStateException("queue is empty");
            return out.pop();
        }
    }

    public static void main(String[] args) {
        MyQueue q = new MyQueue();
        q.enqueue(1); q.enqueue(2); q.enqueue(3);
        System.out.println("enqueue 1 2 3");
        System.out.println("dequeue -> " + q.dequeue());
        q.enqueue(4);
        System.out.println("enqueue 4");
        System.out.println("dequeue -> " + q.dequeue() + " " + q.dequeue() + " " + q.dequeue());
        // Each item is pushed twice and popped twice at most, so n operations cost O(n). Space: O(n).
    }
}

