import java.util.ArrayDeque;

public class Main {
    static class MinStack {
        // each entry is {value, smallest value in the stack when it was pushed}
        private final ArrayDeque<int[]> stack = new ArrayDeque<>();

        void push(int x) {
            int min = stack.isEmpty() ? x : Math.min(x, stack.peek()[1]);
            stack.push(new int[] { x, min });
        }
        int pop() { return stack.pop()[0]; }      // the value and its remembered minimum leave together
        int getMin() { return stack.peek()[1]; }  // O(1): just read the top
    }

    public static void main(String[] args) {
        MinStack s = new MinStack();
        for (int x : new int[] { 5, 3, 7, 3, 2 }) {
            s.push(x);
            System.out.println("push " + x + " -> min " + s.getMin());
        }
        for (int i = 0; i < 2; i++) {
            int x = s.pop();
            System.out.println("pop  " + x + " -> min " + s.getMin());
        }
        // Time: O(1) for push, pop and getMin. Space: O(n), one extra number per item.
    }
}

