class MinStack {
    // each entry is {value, smallest value in the stack when it was pushed}
    private readonly Stack<int[]> stack = new Stack<int[]>();

    public void Push(int x) {
        int min = stack.Count == 0 ? x : Math.Min(x, stack.Peek()[1]);
        stack.Push(new[] { x, min });
    }
    public int Pop() { return stack.Pop()[0]; }       // the value and its remembered minimum leave together
    public int GetMin() { return stack.Peek()[1]; }   // O(1): just read the top
}

class Program {
    static void Main() {
        var s = new MinStack();
        foreach (int x in new[] { 5, 3, 7, 3, 2 }) {
            s.Push(x);
            Console.WriteLine("push " + x + " -> min " + s.GetMin());
        }
        for (int i = 0; i < 2; i++) {
            int x = s.Pop();
            Console.WriteLine("pop  " + x + " -> min " + s.GetMin());
        }
        // Time: O(1) for Push, Pop and GetMin. Space: O(n), one extra number per item.
    }
}

