import java.util.ArrayDeque;
import java.util.Arrays;

public class Main {
    // Time: O(n), each index is pushed once and popped once. Space: O(n).
    static int[] nextGreater(int[] a) {
        int[] result = new int[a.length];
        Arrays.fill(result, -1);                       // -1 means "no greater number to the right"
        ArrayDeque<Integer> waiting = new ArrayDeque<>();   // indexes still waiting for a bigger number
        for (int i = 0; i < a.length; i++) {
            // a[i] answers every waiting index whose value is smaller
            while (!waiting.isEmpty() && a[waiting.peek()] < a[i]) result[waiting.pop()] = a[i];
            waiting.push(i);
        }
        return result;
    }

    static String join(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int x : a) sb.append(sb.length() > 0 ? " " : "").append(x);
        return sb.toString();
    }

    public static void main(String[] args) {
        int[] a = { 2, 1, 5, 3, 6, 4 };
        System.out.println("input:        " + join(a));
        System.out.println("next greater: " + join(nextGreater(a)));
    }
}

