using System;
using System.Collections.Generic;

// A key type whose hash code we can make good or bad, and that counts Equals calls.
class Key {
    public static bool UseBadHash;
    public static long EqualsCalls;
    public readonly int Id;
    public Key(int id) { Id = id; }

    public override int GetHashCode() {
        return UseBadHash ? 1 : Id;     // bad: every key lands in the same bucket
    }
    public override bool Equals(object other) {
        EqualsCalls++;                  // the dictionary calls this only inside one bucket
        return other is Key && ((Key)other).Id == Id;
    }
}

class Program {
    static long Run(bool bad, int n) {
        Key.UseBadHash = bad;
        var map = new Dictionary<Key, int>();
        for (int i = 0; i < n; i++) map[new Key(i)] = i;
        Key.EqualsCalls = 0;
        int found = 0;
        for (int i = 0; i < n; i++) {
            int value;
            if (map.TryGetValue(new Key(i), out value)) found++;   // one hash, one bucket, a few Equals
        }
        if (found != n) throw new Exception("lookup failed");
        return Key.EqualsCalls;
    }

    static void Main() {
        int n = 2000;
        long good = Run(false, n), bad = Run(true, n);
        Console.WriteLine(n + " lookups in a dictionary of " + n + " keys");
        Console.WriteLine("good hash: about " + (good / n) + " Equals call per lookup");
        Console.WriteLine("bad hash:  about " + (bad / n) + " Equals calls per lookup");
        // Good hash: O(1) per lookup on average. Bad hash: O(n) per lookup, O(n^2) in total.
    }
}

