import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static class Node { int val; Node left, right; Node(int v) { val = v; } }

    static Node insert(Node n, int v) {            // builds a small search tree for the demo
        if (n == null) return new Node(v);
        if (v < n.val) n.left = insert(n.left, v); else n.right = insert(n.right, v);
        return n;
    }

    // Time: O(n). Space: O(w), w = the widest row of the tree.
    static List<String> levels(Node root) {
        List<String> rows = new ArrayList<>();
        ArrayDeque<Node> queue = new ArrayDeque<>();
        if (root != null) queue.add(root);
        while (!queue.isEmpty()) {
            int size = queue.size();               // how many nodes are in this row
            StringBuilder row = new StringBuilder();
            for (int i = 0; i < size; i++) {
                Node n = queue.poll();             // take from the front
                row.append(i > 0 ? " " : "").append(n.val);
                if (n.left != null) queue.add(n.left);     // children go to the back
                if (n.right != null) queue.add(n.right);
            }
            rows.add(row.toString());
        }
        return rows;
    }

    public static void main(String[] args) {
        Node root = null;
        for (int v : new int[] { 4, 2, 6, 1, 3, 7 }) root = insert(root, v);
        System.out.println("inserted: 4 2 6 1 3 7");
        List<String> rows = levels(root);
        for (int i = 0; i < rows.size(); i++) System.out.println("level " + i + ": " + rows.get(i));
    }
}

