using System;
using System.Collections.Generic;

class Node { public int val; public Node left, right; public Node(int v) { val = v; } }

class Program {
    static Node Insert(Node n, int v) {            // builds a small search tree for the demo
        if (n == null) return new Node(v);
        if (v < n.val) n.left = Insert(n.left, v); else n.right = Insert(n.right, v);
        return n;
    }

    // Time: O(n). Space: O(w), w = the widest row of the tree.
    static List<string> Levels(Node root) {
        var rows = new List<string>();
        var queue = new Queue<Node>();
        if (root != null) queue.Enqueue(root);
        while (queue.Count > 0) {
            int size = queue.Count;                // how many nodes are in this row
            var row = new List<int>();
            for (int i = 0; i < size; i++) {
                Node n = queue.Dequeue();          // take from the front
                row.Add(n.val);
                if (n.left != null) queue.Enqueue(n.left);     // children go to the back
                if (n.right != null) queue.Enqueue(n.right);
