public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }

    // Time: O(n). Space: O(h) call stack. long limits so int.MinValue and MaxValue are legal values.
    static boolean isValid(Node n, long low, long high) {
        if (n == null) return true;
        if (n.val <= low || n.val >= high) return false;      // outside the allowed range
        return isValid(n.left, low, n.val)                    // left side: everything below n.val
            && isValid(n.right, n.val, high);                 // right side: everything above n.val
    }

    // The common wrong version: compares each node only with its own children.
    static boolean childCheckOnly(Node n) {
        if (n == null) return true;
        if (n.left != null && n.left.val >= n.val) return false;
        if (n.right != null && n.right.val <= n.val) return false;
        return childCheckOnly(n.left) && childCheckOnly(n.right);
    }

    public static void main(String[] args) {
        Node good = new Node(5, new Node(3, null, new Node(4, null, null)), new Node(8, null, null));
        Node bad = new Node(5, new Node(3, null, new Node(6, null, null)), new Node(8, null, null));
        System.out.println("tree A: 5 (3 (-, 4), 8)   tree B: 5 (3 (-, 6), 8)");
        System.out.println("range check A: " + (isValid(good, Long.MIN_VALUE, Long.MAX_VALUE) ? "valid" : "not valid"));
        System.out.println("range check B: " + (isValid(bad, Long.MIN_VALUE, Long.MAX_VALUE) ? "valid" : "not valid"));
        System.out.println("child-only check B: " + (childCheckOnly(bad) ? "valid (wrong!)" : "not valid"));
    }
}

