import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static int[][] graph = { { 1, 2 }, { 0, 3 }, { 0, 4 }, { 1, 5 }, { 2, 5 }, { 3, 4 } };  // adjacency list

    // BFS: a queue, so nodes come out nearest first. Time: O(V + E). Space: O(V).
    static List<String> bfs(int start) {
        List<String> order = new ArrayList<>();
        boolean[] seen = new boolean[graph.length];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(start); seen[start] = true;         // mark when you add, not when you remove
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add("" + node);
            for (int next : graph[node])
                if (!seen[next]) { seen[next] = true; queue.add(next); }
        }
        return order;
    }

    // DFS: recursion, so one path is followed to its end first. Time: O(V + E). Space: O(V).
    static void dfs(int node, boolean[] seen, List<String> order) {
        seen[node] = true;
        order.add("" + node);
        for (int next : graph[node])
            if (!seen[next]) dfs(next, seen, order);
    }

    public static void main(String[] args) {
        System.out.println("edges: 0-1 0-2 1-3 2-4 3-5 4-5");
        System.out.println("BFS from 0: " + String.join(" ", bfs(0)));
        List<String> order = new ArrayList<>();
        dfs(0, new boolean[graph.length], order);
        System.out.println("DFS from 0: " + String.join(" ", order));
    }
}

