        var order = new List<int>();
        var seen = new bool[graph.Length];
        var queue = new Queue<int>();
        queue.Enqueue(start); seen[start] = true;     // mark when you add, not when you remove
        while (queue.Count > 0) {
            int node = queue.Dequeue();
            order.Add(node);
            foreach (int next in graph[node])
                if (!seen[next]) { seen[next] = true; queue.Enqueue(next); }
        }
        return order;
    }

    // DFS: recursion, so one path is followed to its end first. Time: O(V + E). Space: O(V).
    static void Dfs(int node, bool[] seen, List<int> order) {
        seen[node] = true;
        order.Add(node);
        foreach (int next in graph[node])
            if (!seen[next]) Dfs(next, seen, order);
    }

    static void Main() {
        Console.WriteLine("edges: 0-1 0-2 1-3 2-4 3-5 4-5");
        Console.WriteLine("BFS from 0: " + string.Join(" ", Bfs(0)));
        var order = new List<int>();
        Dfs(0, new bool[graph.Length], order);
        Console.WriteLine("DFS from 0: " + string.Join(" ", order));
    }
}

