    // Turn this land cell and all land joined to it into water, so it is counted once only.
    static void sink(char[][] g, int r, int c) {
        if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;
        g[r][c] = '0';
        sink(g, r + 1, c); sink(g, r - 1, c); sink(g, r, c + 1); sink(g, r, c - 1);   // 4 neighbours
    }

    // Time: O(rows * cols), each cell is visited a constant number of times. Space: O(rows * cols) stack at worst.
    static int countIslands(String[] rows) {
        char[][] g = new char[rows.length][];
        for (int r = 0; r < rows.length; r++) g[r] = rows[r].toCharArray();   // work on a copy
        int count = 0;
        for (int r = 0; r < g.length; r++)
            for (int c = 0; c < g[0].length; c++)
                if (g[r][c] == '1') {     // land not seen before: a new island
                    count++;
                    sink(g, r, c);
                }
        return count;
    }

