public class Main {
    static class Node { int val; Node left, right; Node(int v) { val = v; } }

    static Node insert(Node n, int v) {            // builds a small tree for the demo
        if (n == null) return new Node(v);
        if (v < n.val) n.left = insert(n.left, v); else n.right = insert(n.right, v);
        return n;
    }

    // Works for any binary tree (it does not use the search-tree order).
    // Time: O(n). Space: O(h) call stack.
    static Node lca(Node n, int p, int q) {
        if (n == null || n.val == p || n.val == q) return n;   // found a target (or nothing)
        Node left = lca(n.left, p, q);
        Node right = lca(n.right, p, q);
        if (left != null && right != null) return n;   // one target on each side: n is the answer
        return left != null ? left : right;            // pass up whatever was found
    }

    public static void main(String[] args) {
        Node root = null;
        for (int v : new int[] { 4, 2, 6, 1, 3, 5, 7 }) root = insert(root, v);
        System.out.println("tree rows: 4 / 2 6 / 1 3 5 7");
        int[][] pairs = { { 1, 3 }, { 1, 7 }, { 5, 6 } };
        for (int[] pr : pairs)
            System.out.println("LCA of " + pr[0] + " and " + pr[1] + " = " + lca(root, pr[0], pr[1]).val);
    }
}

