import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Main {
    // edges are {before, after}. Time: O(V + E). Space: O(V + E).
    static List<Integer> order(int n, int[][] edges) {
        List<List<Integer>> next = new ArrayList<>();
        for (int i = 0; i < n; i++) next.add(new ArrayList<>());
        int[] waitingFor = new int[n];               // how many prerequisites are not done yet
        for (int[] e : edges) { next.get(e[0]).add(e[1]); waitingFor[e[1]]++; }
        ArrayDeque<Integer> ready = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (waitingFor[i] == 0) ready.add(i);
        List<Integer> result = new ArrayList<>();
        while (!ready.isEmpty()) {
            int task = ready.poll();
            result.add(task);
            for (int t : next.get(task))             // this task is done: its followers wait for one less
                if (--waitingFor[t] == 0) ready.add(t);
        }
        return result;                               // fewer than n tasks means there is a cycle
    }

    static void report(String name, int n, int[][] edges) {
        List<Integer> r = order(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int x : r) sb.append(sb.length() > 0 ? " " : "").append(x);
        if (r.size() == n) System.out.println(name + ": order " + sb);
        else System.out.println(name + ": impossible, only " + r.size() + " of " + n + " tasks can be ordered");
    }

    public static void main(String[] args) {
        int[][] a = { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 }, { 3, 4 } };
        int[][] b = { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 }, { 3, 4 }, { 4, 1 } };
        report("6 tasks, edges 0>1 0>2 1>3 2>3 3>4", 6, a);
        report("same plus 4>1", 6, b);
    }
}

