vector<int> order(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> next(n);
    vector<int> waitingFor(n, 0);                // how many prerequisites are not done yet
    for (auto& e : edges) { next[e.first].push_back(e.second); waitingFor[e.second]++; }
    queue<int> ready;
    for (int i = 0; i < n; i++) if (waitingFor[i] == 0) ready.push(i);
    vector<int> result;
    while (!ready.empty()) {
        int task = ready.front(); ready.pop();
        result.push_back(task);
        for (int t : next[task])                 // this task is done: its followers wait for one less
            if (--waitingFor[t] == 0) ready.push(t);
    }
    return result;                               // fewer than n tasks means there is a cycle
}

