public class Main {
    // state: 0 = not visited, 1 = on the path we are walking now, 2 = finished
    static boolean dfs(int[][] g, int node, int[] state) {
        state[node] = 1;
        for (int next : g[node]) {
            if (state[next] == 1) return true;                      // back to our own path: a cycle
            if (state[next] == 0 && dfs(g, next, state)) return true;
        }
        state[node] = 2;                                            // everything below is safe
        return false;
    }

    // Time: O(V + E). Space: O(V).
    static boolean hasCycle(int[][] g) {
        int[] state = new int[g.length];
        for (int i = 0; i < g.length; i++)                          // the graph may be in several pieces
            if (state[i] == 0 && dfs(g, i, state)) return true;
        return false;
    }

    public static void main(String[] args) {
        int[][] diamond = { { 1, 2 }, { 3 }, { 3 }, {} };           // 0>1 0>2 1>3 2>3
        int[][] loop = { { 1, 2 }, { 3 }, { 3 }, { 1 } };           // the same plus 3>1
        System.out.println("0>1 0>2 1>3 2>3      cycle: " + (hasCycle(diamond) ? "yes" : "no"));
        System.out.println("0>1 0>2 1>3 2>3 3>1  cycle: " + (hasCycle(loop) ? "yes" : "no"));
    }
}

