import java.util.HashMap;
import java.util.Map;

public class Main {
    static class Node { int key, val; Node prev, next; Node(int k, int v) { key = k; val = v; } }

    static class LRU {
        final int cap; final Map<Integer, Node> map = new HashMap<>();
        final Node head = new Node(0, 0), tail = new Node(0, 0);   // dummy ends: newest after head
        LRU(int cap) { this.cap = cap; head.next = tail; tail.prev = head; }
        void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
        void addFront(Node n) { n.next = head.next; n.prev = head; head.next.prev = n; head.next = n; }
        int get(int k) {                                   // O(1)
            Node n = map.get(k);
            if (n == null) return -1;
            unlink(n); addFront(n);                        // now the most recently used
            return n.val;
        }
        void put(int k, int v) {                           // O(1)
            Node n = map.get(k);
            if (n != null) { n.val = v; unlink(n); addFront(n); return; }
            if (map.size() == cap) { Node old = tail.prev; unlink(old); map.remove(old.key); }  // evict oldest
            n = new Node(k, v); map.put(k, n); addFront(n);
        }
    }

    public static void main(String[] args) {
        LRU c = new LRU(2);
        c.put(1, 10); c.put(2, 20);
        System.out.println("get 1 -> " + c.get(1));
        c.put(3, 30);                                      // evicts key 2
        System.out.println("get 2 -> " + c.get(2));
        System.out.println("get 3 -> " + c.get(3));
        // Space: O(capacity).
    }
}

