#include <bits/stdc++.h>
using namespace std;

// std::list is a doubly linked list; the map stores an iterator to each node.
class LRU {
    int cap;
    list<pair<int, int>> order;                       // front = newest, back = oldest
    unordered_map<int, list<pair<int, int>>::iterator> pos;
public:
    LRU(int c) : cap(c) {}
    int get(int k) {                                  // O(1)
        auto it = pos.find(k);
        if (it == pos.end()) return -1;
        order.splice(order.begin(), order, it->second);   // move node to the front
        return it->second->second;
    }
    void put(int k, int v) {                          // O(1)
        auto it = pos.find(k);
        if (it != pos.end()) { it->second->second = v; order.splice(order.begin(), order, it->second); return; }
        if ((int)order.size() == cap) { pos.erase(order.back().first); order.pop_back(); }   // evict oldest
        order.push_front({k, v});
        pos[k] = order.begin();
    }
};

int main() {
    LRU c(2);
    c.put(1, 10); c.put(2, 20);
    cout << "get 1 -> " << c.get(1) << "\n";
    c.put(3, 30);                                     // evicts key 2
    cout << "get 2 -> " << c.get(2) << "\n";
    cout << "get 3 -> " << c.get(3) << "\n";
    // Space: O(capacity).
}

