using System;
using System.Collections.Generic;

class LRU {
    private readonly int cap;
    private readonly Dictionary<int, LinkedListNode<int[]>> map = new Dictionary<int, LinkedListNode<int[]>>();
    private readonly LinkedList<int[]> order = new LinkedList<int[]>();   // first = newest, last = oldest

    public LRU(int cap) { this.cap = cap; }

    public int Get(int k) {                           // O(1)
        LinkedListNode<int[]> n;
        if (!map.TryGetValue(k, out n)) return -1;
        order.Remove(n); order.AddFirst(n);           // now the most recently used
        return n.Value[1];
    }
    public void Put(int k, int v) {                   // O(1)
        LinkedListNode<int[]> n;
        if (map.TryGetValue(k, out n)) { n.Value[1] = v; order.Remove(n); order.AddFirst(n); return; }
        if (map.Count == cap) {                       // evict oldest
            var old = order.Last; order.RemoveLast(); map.Remove(old.Value[0]);
        }
        map[k] = order.AddFirst(new[] { k, v });
    }
}

