public class Main {
    // Time: O(n log k). Space: O(n) for the counts, O(k) for the heap.
    static List<Integer> topK(int[] a, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : a) count.merge(x, 1, Integer::sum);          // count each number
        // min-heap ordered by count: the weakest of the best k sits on top
        PriorityQueue<Integer> heap = new PriorityQueue<>((x, y) -> count.get(x) - count.get(y));
        for (int x : count.keySet()) {
            heap.add(x);
            if (heap.size() > k) heap.poll();                     // drop the least frequent
        }
        List<Integer> result = new ArrayList<>(heap);
        result.sort((x, y) -> count.get(y) - count.get(x));       // most frequent first
        return result;
    }

    public static void main(String[] args) {
        int[] a = { 1, 1, 1, 2, 2, 3, 3, 3, 3, 4 };
        System.out.println("input: " + Arrays.toString(a));
        System.out.println("top 2: " + topK(a, 2));
    }
