// Tiny min-heap on [count, number] pairs (JavaScript has no built-in heap).
class MinHeap {
  constructor() { this.h = []; }
  get size() { return this.h.length; }
  push(v) {
    const h = this.h; h.push(v);
    for (let i = h.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (h[p][0] <= h[i][0]) break;
      [h[p], h[i]] = [h[i], h[p]]; i = p;
    }
  }
  pop() {
    const h = this.h, top = h[0], last = h.pop();
    if (h.length) {
      h[0] = last;
      for (let i = 0;;) {
        let s = i; const l = 2 * i + 1, r = l + 1;
        if (l < h.length && h[l][0] < h[s][0]) s = l;
        if (r < h.length && h[r][0] < h[s][0]) s = r;
        if (s === i) break;
        [h[s], h[i]] = [h[i], h[s]]; i = s;
      }
    }
    return top;
  }
}

// Time: O(n log k). Space: O(n) for the counts, O(k) for the heap.
function topK(a, k) {
  const count = new Map();
  for (const x of a) count.set(x, (count.get(x) || 0) + 1);   // count each number
  const heap = new MinHeap();
  for (const [x, c] of count) {
    heap.push([c, x]);
    if (heap.size > k) heap.pop();                            // drop the least frequent
  }
  return heap.h.sort((p, q) => q[0] - p[0]).map(p => p[1]);   // most frequent first
}

