// Time: O(n log k). Space: O(n) for the counts, O(k) for the heap.
vector<int> topK(const vector<int>& a, int k) {
    unordered_map<int, int> count;
    for (int x : a) count[x]++;                              // count each number
    // min-heap of (count, number): the weakest of the best k sits on top
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;
    for (auto& [x, c] : count) {
