using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    // Time: O(n log k). Space: O(n) for the counts, O(k) for the heap.
    // SortedSet of (count, number) works as a min-heap here because the pairs are unique.
    static List<int> TopK(int[] a, int k) {
        var count = new Dictionary<int, int>();
        foreach (int x in a) { int c; count.TryGetValue(x, out c); count[x] = c + 1; }   // count each number
        var heap = new SortedSet<Tuple<int, int>>();
        foreach (var kv in count) {
            heap.Add(Tuple.Create(kv.Value, kv.Key));
            if (heap.Count > k) heap.Remove(heap.Min);          // drop the least frequent
        }
        return heap.Reverse().Select(t => t.Item2).ToList();    // most frequent first
    }

    static void Main() {
        int[] a = { 1, 1, 1, 2, 2, 3, 3, 3, 3, 4 };
        Console.WriteLine("input: [" + string.Join(", ", a) + "]");
        Console.WriteLine("top 2: [" + string.Join(", ", TopK(a, 2)) + "]");
    }
}

