public class Main {
    static int[] parent, size;
    static int groups;

    static int find(int x) {                       // path compression: point straight at the root
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;                      // already in the same group
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;                           // attach the smaller tree under the bigger
        size[ra] += size[rb];
        groups--;
    }

    public static void main(String[] args) {
        int n = 6;
        parent = new int[n]; size = new int[n]; groups = n;
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }   // everyone starts alone
        int[][] pairs = { { 0, 1 }, { 1, 2 }, { 3, 4 }, { 2, 0 } };
        System.out.println("6 people, friend pairs: 0-1 1-2 3-4 2-0");
        for (int[] p : pairs) {
            union(p[0], p[1]);
            System.out.println("after " + p[0] + "-" + p[1] + ": groups = " + groups);
        }
        // Time: almost O(1) per operation. Space: O(n).
    }
}

