vector<int> parent_, size_;
int groups;

int find(int x) {                              // path compression: point straight at the root
    if (parent_[x] != x) parent_[x] = find(parent_[x]);
    return parent_[x];
}

void unite(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return;                      // already in the same group
    if (size_[ra] < size_[rb]) swap(ra, rb);
    parent_[rb] = ra;                          // attach the smaller tree under the bigger
    size_[ra] += size_[rb];
    groups--;
}

