using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

// A small LRU cache that is safe for many threads and loads each missing key once.
class SafeCache<TKey, TValue> {
    private class Entry { public TValue Value; public LinkedListNode<TKey> Node; }
    private readonly int capacity;
    private readonly object gate = new object();
    private readonly LinkedList<TKey> order = new LinkedList<TKey>();                  // first = newest
    private readonly Dictionary<TKey, Entry> map = new Dictionary<TKey, Entry>();
    private readonly Dictionary<TKey, Lazy<TValue>> loading = new Dictionary<TKey, Lazy<TValue>>();                   // loads in flight

    public SafeCache(int capacity) { this.capacity = capacity; }

    public TValue GetOrAdd(TKey key, Func<TKey, TValue> load) {
        Lazy<TValue> pending;
        lock (gate) {
            Entry hit;
            if (map.TryGetValue(key, out hit)) {                // cache hit: mark as newest
                order.Remove(hit.Node); order.AddFirst(hit.Node);
                return hit.Value;
            }
            if (!loading.TryGetValue(key, out pending)) {           // first caller starts the load
                pending = new Lazy<TValue>(() => load(key), LazyThreadSafetyMode.ExecutionAndPublication);
                loading[key] = pending;
            }
        }
        TValue value = pending.Value;                               // slow work runs outside the lock
        lock (gate) {
            if (loading.Remove(key) && !map.ContainsKey(key)) {
                if (map.Count == capacity) {                        // evict the oldest
                    var oldest = order.Last; order.RemoveLast(); map.Remove(oldest.Value);
                }
                map[key] = new Entry { Value = value, Node = order.AddFirst(key) };
            }
        }
        return value;
    }
}

class Program {
    static int loads;

    static void Main() {
        var cache = new SafeCache<int, string>(2);
        var tasks = new List<Task>();
        for (int i = 0; i < 20; i++)                                // 20 callers ask for the same key
            tasks.Add(Task.Run(() => cache.GetOrAdd(7, k => { Interlocked.Increment(ref loads); Thread.Sleep(50); return "value" + k; })));
        Task.WaitAll(tasks.ToArray());
        Console.WriteLine("20 concurrent requests for key 7");
        Console.WriteLine("times the loader ran: " + loads);
        Console.WriteLine("later request returns: " + cache.GetOrAdd(7, k => "never called"));
        // Time: O(1) per hit. Space: O(capacity). Only one loader per key runs at a time.
    }
}

