public class Main {
    // 1) Sum 1..n. Base case: n == 0. Smaller problem: n - 1.  Time O(n), space O(n) call stack.
    static int sum(int n) {
        if (n == 0) return 0;              // base case: the call that stops the chain
        return n + sum(n - 1);             // the same problem, smaller
    }

    // 2) Reverse a string with recursion.
    static String reverse(String s) {
        if (s.length() <= 1) return s;
        return reverse(s.substring(1)) + s.charAt(0);
    }

    // 3) Missing base case: the depth grows until the stack is full.
    static int broken(int n) { return n + broken(n - 1); }

    public static void main(String[] args) {
        System.out.println("sum(5) = " + sum(5));
        System.out.println("reverse(\"abc\") = " + reverse("abc"));
        try { broken(5); }
        catch (StackOverflowError e) { System.out.println("no base case -> StackOverflowError"); }
    }
}

