import java.util.HashMap;
import java.util.Map;

public class Main {
    static long calls;

    // 1) Plain recursion. Time: O(2^n). Space: O(n) call stack.
    static long plain(int n) { calls++; return n < 2 ? n : plain(n - 1) + plain(n - 2); }

    // 2) Memoisation: save each answer the first time. Time: O(n). Space: O(n).
    static long memo(int n, Map<Integer, Long> saved) {
        if (n < 2) return n;
        if (saved.containsKey(n)) return saved.get(n);
        long r = memo(n - 1, saved) + memo(n - 2, saved);
        saved.put(n, r);
        return r;
    }

    // 3) Bottom-up: keep only the last two values. Time: O(n). Space: O(1).
    static long bottomUp(int n) {
        long a = 0, b = 1;
        for (int i = 0; i < n; i++) { long t = a + b; a = b; b = t; }
        return a;
    }

    public static void main(String[] args) {
        int n = 30;
        System.out.println("fib(" + n + ") plain:     " + plain(n) + " (" + calls + " calls)");
        System.out.println("fib(" + n + ") memo:      " + memo(n, new HashMap<>()));
        System.out.println("fib(" + n + ") bottom-up: " + bottomUp(n));
    }
}

