import java.util.Arrays;

public class Main {
    static long calls;

    // Top-down (memoisation): recursion plus a saved-answers array. Number of ways to make `total` with coins.
    static long topDown(int total, int[] coins, long[] saved) {
        calls++;
        if (total == 0) return 1;
        if (total < 0) return 0;
        if (saved[total] != -1) return saved[total];       // already solved
        long ways = 0;
        for (int c : coins) ways += topDown(total - c, coins, saved);
        return saved[total] = ways;
    }

    // Bottom-up (tabulation): fill the table from 0 upwards. Time: O(total * coins). Space: O(total).
    static long bottomUp(int total, int[] coins) {
        long[] dp = new long[total + 1];
        dp[0] = 1;
        for (int t = 1; t <= total; t++)
            for (int c : coins) if (t - c >= 0) dp[t] += dp[t - c];
        return dp[total];
    }

    public static void main(String[] args) {
        int[] coins = { 1, 2, 5 };
        long[] saved = new long[26];
        Arrays.fill(saved, -1);
        System.out.println("ordered ways to make 25 from coins 1, 2, 5");
        System.out.println("top-down:  " + topDown(25, coins, saved) + " (" + calls + " calls)");
        System.out.println("bottom-up: " + bottomUp(25, coins));
    }
}

