import java.util.Arrays;

public class Main {
    // Time: O(amount * coins). Space: O(amount).
    static int fewestCoins(int[] coins, int amount) {
        int INF = amount + 1;                         // bigger than any real answer
        int[] dp = new int[amount + 1];               // dp[a] = fewest coins to make a
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins)
                if (c <= a && dp[a - c] + 1 < dp[a]) dp[a] = dp[a - c] + 1;   // c is the last coin
        return dp[amount] >= INF ? -1 : dp[amount];
    }

    public static void main(String[] args) {
        int[] coins = { 1, 3, 4 };
        System.out.println("coins 1, 3, 4");
        System.out.println("amount 6:  " + fewestCoins(coins, 6) + " coins (greedy would use 3)");
        System.out.println("amount 11: " + fewestCoins(coins, 11) + " coins");
        System.out.println("coins 5, 10, amount 3: " + fewestCoins(new int[] { 5, 10 }, 3));
    }
}

