import java.util.ArrayList;
import java.util.List;

public class Main {
    // Time: O(n * 2^n). Space: O(n) recursion depth, not counting the output.
    static void build(int[] a, int i, List<Integer> current, List<String> out) {
        if (i == a.length) { out.add(current.toString()); return; }   // every number has been decided
        current.add(a[i]);                         // choice 1: take a[i]
        build(a, i + 1, current, out);
        current.remove(current.size() - 1);        // undo the choice (the "back" in backtracking)
        build(a, i + 1, current, out);             // choice 2: leave a[i]
    }

    public static void main(String[] args) {
        int[] a = { 1, 2, 3 };
        List<String> out = new ArrayList<>();
        build(a, 0, new ArrayList<>(), out);
        System.out.println("numbers: [1, 2, 3]");
        System.out.println("subsets (" + out.size() + "): " + String.join(" ", out));
    }
}

