    // Time: O(n * n!). Space: O(n) recursion depth plus the used array.
    static void build(int[] a, boolean[] used, List<Integer> current, List<String> out) {
        if (current.size() == a.length) { out.add(current.toString()); return; }   // all positions filled
        for (int i = 0; i < a.length; i++) {
