import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    // tails.get(k) = the smallest value that can end an increasing run of length k + 1.
    // Time: O(n log n), a binary search per number. Space: O(n).
    static int lis(int[] a) {
        List<Integer> tails = new ArrayList<>();
        for (int x : a) {
            int pos = Collections.binarySearch(tails, x);
            if (pos < 0) pos = -pos - 1;                 // first place where tails >= x
            if (pos == tails.size()) tails.add(x);       // x extends the longest run
            else tails.set(pos, x);                      // x is a smaller end for a run of that length
        }
        return tails.size();
    }

    public static void main(String[] args) {
        int[][] tests = { { 10, 9, 2, 5, 3, 7, 101, 18 }, { 0, 1, 0, 3, 2, 3 }, { 7, 7, 7, 7 } };
        for (int[] t : tests)
            System.out.println(java.util.Arrays.toString(t) + " -> LIS length " + lis(t));
    }
}

