  for (const x of a) {
    let lo = 0, hi = tails.length;              // find the first place where tails >= x
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1; else hi = mid;
    }
    if (lo === tails.length) tails.push(x);     // x extends the longest run
    else tails[lo] = x;                         // x is a smaller end for a run of that length
  }
