public class Main {
    // dp[i][j] = fewest edits to turn the first i letters of a into the first j letters of b.
    // Time: O(m * n). Space: O(m * n).
    static int editDistance(String a, String b) {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 0; i <= a.length(); i++) dp[i][0] = i;     // delete all i letters
        for (int j = 0; j <= b.length(); j++) dp[0][j] = j;     // insert all j letters
        for (int i = 1; i <= a.length(); i++)
            for (int j = 1; j <= b.length(); j++) {
                int same = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                dp[i][j] = Math.min(dp[i - 1][j - 1] + same,                     // replace (or keep)
                           Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1));        // delete, insert
            }
        return dp[a.length()][b.length()];
    }

    public static void main(String[] args) {
        String[][] tests = { { "kitten", "sitting" }, { "horse", "ros" }, { "same", "same" } };
        for (String[] t : tests)
            System.out.println(t[0] + " -> " + t[1] + ": " + editDistance(t[0], t[1]) + " edits");
    }
}

