public class Main {
    static int count;

    // Place one queen per row. cols / d1 / d2 mark the columns and the two diagonals already attacked.
    // Time: roughly O(n!) in the worst case, much less with pruning. Space: O(n).
    static void place(int row, int n, boolean[] cols, boolean[] d1, boolean[] d2) {
        if (row == n) { count++; return; }              // all rows have a queen
        for (int col = 0; col < n; col++) {
            if (cols[col] || d1[row - col + n] || d2[row + col]) continue;   // attacked: skip
            cols[col] = d1[row - col + n] = d2[row + col] = true;            // place
            place(row + 1, n, cols, d1, d2);
            cols[col] = d1[row - col + n] = d2[row + col] = false;           // remove (backtrack)
        }
    }

    public static void main(String[] args) {
