public class Main {
    // dp[w] = best value using capacity w. Loop w downwards so each item is used at most once.
    // Time: O(items * capacity). Space: O(capacity).
    static int knapsack(int[] weight, int[] value, int capacity) {
        int[] dp = new int[capacity + 1];
        for (int i = 0; i < weight.length; i++)
            for (int w = capacity; w >= weight[i]; w--)
                dp[w] = Math.max(dp[w], dp[w - weight[i]] + value[i]);   // leave the item, or take it
        return dp[capacity];
    }

    public static void main(String[] args) {
        int[] weight = { 1, 3, 4, 5 }, value = { 1, 4, 5, 7 };
        System.out.println("weights 1 3 4 5, values 1 4 5 7");
        for (int cap : new int[] { 7, 9, 10 })
            System.out.println("capacity " + cap + ": best value " + knapsack(weight, value, cap));
    }
}

