public class Main {
    // Full table: O(m * n) memory.
    static int lcsFull(String a, String b) {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 1; i <= a.length(); i++)
            for (int j = 1; j <= b.length(); j++)
                dp[i][j] = a.charAt(i - 1) == b.charAt(j - 1) ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
        return dp[a.length()][b.length()];
    }

    // Two rows: each row reads only the row above it. Memory: O(n). Time is still O(m * n).
    static int lcsTwoRows(String a, String b) {
        int[] prev = new int[b.length() + 1], cur = new int[b.length() + 1];
        for (int i = 1; i <= a.length(); i++) {
            for (int j = 1; j <= b.length(); j++)
                cur[j] = a.charAt(i - 1) == b.charAt(j - 1) ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
            int[] t = prev; prev = cur; cur = t;       // the finished row becomes "previous"
        }
        return prev[b.length()];
    }

    public static void main(String[] args) {
        String a = "ABCBDABXYZ", b = "BDCABAXZY";
        System.out.println("full table: " + lcsFull(a, b) + " (" + (a.length() + 1) * (b.length() + 1) + " cells)");
        System.out.println("two rows:   " + lcsTwoRows(a, b) + " (" + 2 * (b.length() + 1) + " cells)");
    }
}

