public class Main {
    // Try dividers only up to sqrt(n). Time: O(sqrt n). Space: O(1).
    static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (int d = 3; (long) d * d <= n; d += 2)      // odd dividers only
            if (n % d == 0) return false;
        return true;
    }

    // Euclid: gcd(a, b) = gcd(b, a % b). Time: O(log min(a, b)). Space: O(1).
    static int gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }

    public static void main(String[] args) {
        for (int n : new int[] { 1, 2, 17, 21, 97, 1000003 })
            System.out.println(n + (isPrime(n) ? " is prime" : " is not prime"));
        System.out.println("gcd(48, 18) = " + gcd(48, 18));
        System.out.println("gcd(17, 5) = " + gcd(17, 5));
    }
}

