public class Main {
    // Factorial with a loop. Time: O(n). Space: O(1). long overflows after 20!.
    static long factorial(int n) {
        long r = 1;
        for (int i = 2; i <= n; i++) r *= i;
        return r;
    }

    // FizzBuzz: check the "both" case first. Time: O(n).
    static String fizzBuzz(int i) {
        if (i % 15 == 0) return "FizzBuzz";
        if (i % 3 == 0) return "Fizz";
        if (i % 5 == 0) return "Buzz";
        return String.valueOf(i);
    }

    // Armstrong: the sum of each digit to the power of the digit count equals the number. Time: O(d).
    static boolean isArmstrong(int n) {
        int digits = String.valueOf(n).length(), sum = 0;
        for (int x = n; x > 0; x /= 10) sum += (int) Math.pow(x % 10, digits);
        return sum == n;
    }

    public static void main(String[] args) {
        System.out.println("5! = " + factorial(5) + ", 20! = " + factorial(20));
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 15; i++) sb.append(i > 1 ? " " : "").append(fizzBuzz(i));
        System.out.println("FizzBuzz 1..15: " + sb);
        for (int n : new int[] { 153, 370, 371, 100 })
            System.out.println(n + (isArmstrong(n) ? " is an Armstrong number" : " is not an Armstrong number"));
    }
}

