using namespace std;

// Factorial with a loop. Time: O(n). Space: O(1). long long overflows after 20!.
long long factorial(int n) {
    long long r = 1;
    for (int i = 2; i <= n; i++) r *= i;
    return r;
}

// FizzBuzz: check the "both" case first. Time: O(n).
string fizzBuzz(int i) {
    if (i % 15 == 0) return "FizzBuzz";
    if (i % 3 == 0) return "Fizz";
    if (i % 5 == 0) return "Buzz";
    return to_string(i);
}

// Armstrong: the sum of each digit to the power of the digit count equals the number. Time: O(d).
bool isArmstrong(int n) {
    int digits = to_string(n).size(), sum = 0;
    for (int x = n; x > 0; x /= 10) {
        int p = 1;
        for (int k = 0; k < digits; k++) p *= x % 10;
        sum += p;
    }
    return sum == n;
}

int main() {
    cout << "5! = " << factorial(5) << ", 20! = " << factorial(20) << "\n";
    string line;
    for (int i = 1; i <= 15; i++) line += (i > 1 ? " " : "") + fizzBuzz(i);
    cout << "FizzBuzz 1..15: " << line << "\n";
    for (int n : {153, 370, 371, 100})
        cout << n << (isArmstrong(n) ? " is an Armstrong number" : " is not an Armstrong number") << "\n";
}

