public class Main {
    // XOR of equal numbers is 0 and x ^ 0 = x, so all pairs cancel. Time: O(n). Space: O(1).
    static int single(int[] a) {
        int x = 0;
        for (int v : a) x ^= v;
        return x;
    }

    public static void main(String[] args) {
        int[] a = { 4, 1, 2, 1, 2 };
        System.out.println("input: " + java.util.Arrays.toString(a));
        System.out.println("the single number: " + single(a));

        int p = 5, q = 9;
        System.out.println("before swap: p = " + p + ", q = " + q);
        p ^= q;          // p now holds p XOR q
        q ^= p;          // q XOR (p XOR q) = the old p
        p ^= q;          // (p XOR q) XOR old p = the old q
        System.out.println("after swap:  p = " + p + ", q = " + q);
    }
}

