public class Main {
    // n & (n - 1) removes the lowest 1 bit. A power of two has just one 1 bit. Time: O(1).
    static boolean isPowerOfTwo(int n) { return n > 0 && (n & (n - 1)) == 0; }

    // Kernighan: each loop removes one 1 bit, so it runs once per 1 bit. Time: O(number of 1 bits).
    static int countBits(int n) {
        int count = 0;
        while (n != 0) { n &= n - 1; count++; }
        return count;
    }

    public static void main(String[] args) {
        for (int n : new int[] { 1, 6, 8, 12, 64, 255 })
            System.out.println(n + " = " + Integer.toBinaryString(n) + " -> power of two: " + isPowerOfTwo(n)
                + ", 1 bits: " + countBits(n));
    }
}

