using System;

class Program {
    // Average of two numbers: the naive a + b can overflow int even when the answer fits.
    static int AverageNaive(int a, int b) { return (a + b) / 2; }
    static int AverageSafe(int a, int b) { return a + (b - a) / 2; }   // never adds two large values

    static void Main() {
        int max = int.MaxValue;
        Console.WriteLine("int.MaxValue = " + max);
        Console.WriteLine("MaxValue + 1 (unchecked) = " + unchecked(max + 1));   // wraps to the minimum, no error

        try {
            int boom = checked(max + 1);                                          // checked: throws instead
            Console.WriteLine(boom);
        } catch (OverflowException) {
            Console.WriteLine("checked(MaxValue + 1) throws OverflowException");
        }

        long wide = (long)max + 1;                                                // widen BEFORE the arithmetic
        Console.WriteLine("(long)MaxValue + 1 = " + wide);

        int big = 2000000000;
        Console.WriteLine("average of 2000000000 and 2000000000, naive: " + AverageNaive(big, big));
        Console.WriteLine("average of 2000000000 and 2000000000, safe:  " + AverageSafe(big, big));
        Console.WriteLine("mistake: (long)(big * 2) = " + (long)unchecked(big * 2) + " (cast came too late)");
        // Time: O(1). Space: O(1).
    }
}

