import java.util.ArrayList;
import java.util.List;

public class Main {
    // Sieve: cross out multiples of each prime, starting at p * p. Time: O(n log log n). Space: O(n).
    static List<Integer> sieve(int n) {
        boolean[] composite = new boolean[n + 1];
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (composite[i]) continue;
            primes.add(i);
            for (long j = (long) i * i; j <= n; j += i) composite[(int) j] = true;
        }
        return primes;
    }

    // Fast power: square the base and halve the exponent. Time: O(log exp). Space: O(1).
    static long power(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;   // this bit of the exponent is set
            base = base * base % mod;                           // base, base^2, base^4, ...
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println("primes up to 50: " + sieve(50));
        System.out.println("primes up to 100000: " + sieve(100000).size());
        System.out.println("2^10 mod 1000000007 = " + power(2, 10, 1000000007L));
        System.out.println("3^200 mod 1000000007 = " + power(3, 200, 1000000007L));
    }
}

